from paths import *
p=STUDIO/'source/adventure-ui.js';s=p.read_text(encoding='utf-8')
s=s.replace('load(s){this.close(false);','load(s){this.endingShown=false;this.close(false);')
s=s.replace('playMedia(m,a){','playMedia(m,a,back=null){')
s=s.replace("else this.button(b,'В журнал',()=>this.journal());", "else this.button(b,back?'К финалу':'В журнал',()=>back?back():this.journal());")
s=s.replace("this.button(b,'Закрыть без отметки просмотра',()=>this.close());", "this.button(b,'Закрыть без отметки просмотра',()=>back?back():this.close());")
s=s.replace("this.playMedia(this.data.media.find(m=>m.id===e.media),null)", "this.playMedia(this.data.media.find(m=>m.id===e.media),null,()=>this.ending())")
p.write_text(s,encoding='utf-8')
p=STUDIO/'source/game-runtime.html';s=p.read_text(encoding='utf-8')
s=s.replace('const adventureVariantsApplied={};','const adventureVariantsApplied={};let adventureBasePanoramas=null;')
s=s.replace('function adventureSetup(){if(!game.story?.adventure)return;', 'function adventureSetup(){if(!game.story?.adventure)return;adventureBasePanoramas={...game.panoramas};')
s=s.replace("asset=game.assets[meta?.variantAssets?.[variant]];", "asset=game.assets[meta?.variantAssets?.[variant]]||adventureBasePanoramas[rid];")
s=s.replace("if(adventurePlayer)adventurePlayer.endingShown=false;adventurePlayer?.reset();", "if(adventurePlayer){adventurePlayer.endingShown=false;Object.assign(game.panoramas,adventureBasePanoramas);for(const key of Object.keys(adventureVariantsApplied))delete adventureVariantsApplied[key];cache.clear();}adventurePlayer?.reset();")
p.write_text(s,encoding='utf-8')
